"""SnakeRule: toward the food unless fatal next step, with a one-sentence description (SNAKE-07)."""

import numpy as np

from rllab.baselines.snake import SnakeRule

STRAIGHT, LEFT, RIGHT = 0, 1, 2
UP, EAST, DOWN, WEST = 0, 1, 2, 3


def observe(danger: tuple[int, int, int], heading: int, food: set[int]) -> list[float]:
    """One snake observation: danger per action, heading flags, food-direction flags."""
    heading_flags = [float(d == heading) for d in range(4)]
    food_flags = [float(d in food) for d in range(4)]
    return [float(d) for d in danger] + heading_flags + food_flags


def act(*rows: list[float]) -> list[int]:
    actions = SnakeRule().act(np.array(rows, np.float32), np.random.default_rng(0))
    return [int(a) for a in actions]


def test_snakerule_moves_right_toward_food_on_a_free_cell() -> None:
    assert act(observe((0, 0, 0), UP, {EAST})) == [RIGHT]


def test_snakerule_goes_straight_when_the_food_is_ahead() -> None:
    assert act(observe((0, 0, 0), EAST, {EAST})) == [STRAIGHT]


def test_snakerule_avoids_a_fatal_move_toward_food() -> None:
    assert act(observe((0, 0, 1), UP, {EAST})) == [LEFT]
    assert act(observe((1, 0, 1), UP, {EAST})) == [LEFT]
    assert act(observe((0, 1, 1), UP, {EAST})) == [STRAIGHT]


def test_snakerule_takes_another_food_direction_before_a_fatal_one() -> None:
    assert act(observe((0, 0, 1), UP, {EAST, UP})) == [STRAIGHT]


def test_snakerule_turns_when_the_food_is_behind() -> None:
    assert act(observe((0, 0, 0), UP, {DOWN})) == [LEFT]


def test_snakerule_turns_away_from_danger_when_the_food_is_behind() -> None:
    assert act(observe((0, 1, 0), UP, {DOWN})) == [RIGHT]


def test_snakerule_acts_once_per_agent() -> None:
    rows = (observe((0, 0, 0), UP, {WEST}), observe((0, 0, 0), WEST, {DOWN}))
    assert act(*rows) == [LEFT, LEFT]


def test_snakerule_goes_straight_when_every_move_is_fatal() -> None:
    assert act(observe((1, 1, 1), UP, {EAST})) == [STRAIGHT]


def test_snakerule_description_is_one_sentence() -> None:
    description = SnakeRule().description
    assert description.endswith(".")
    assert ". " not in description
"""Unit tests of `baselines.RandomPolicy`: uniform draws inside the declared action format."""

import json
from pathlib import Path

import numpy as np

from rllab.baselines import RandomPolicy
from rllab.core import Box, Discrete

SAMPLES = Path(__file__).parents[2] / "contracts" / "baselines.RandomPolicy" / "samples"


def play(policy: RandomPolicy, agents: int, seed: int, steps: int = 100) -> np.ndarray:
    rng = np.random.default_rng(seed)
    obs = np.zeros((agents, 7), np.float32)
    return np.stack([policy.act(obs, rng) for _ in range(steps)])


def test_discrete_draws_are_ints_inside_n_and_cover_every_action() -> None:
    actions = play(RandomPolicy(Discrete(3)), agents=2, seed=1)
    assert actions.shape == (100, 2)
    assert np.issubdtype(actions.dtype, np.integer)
    assert set(np.unique(actions).tolist()) == {0, 1, 2}


def test_box_draws_are_dims_floats_inside_the_bounds() -> None:
    actions = play(RandomPolicy(Box(2, -0.5, 2.0)), agents=3, seed=2)
    assert actions.shape == (100, 3, 2)
    assert actions.min() >= -0.5
    assert actions.max() <= 2.0
    # uniform over [-0.5, 2.0]: 600 draws spread well past the middle on both sides
    assert actions.min() < 0.0
    assert actions.max() > 1.5


def test_one_action_per_agent_row() -> None:
    rng = np.random.default_rng(0)
    assert RandomPolicy(Discrete(4)).act(np.zeros((5, 3)), rng).shape == (5,)
    assert RandomPolicy(Box(3, 0.0, 1.0)).act(np.zeros((1, 3)), rng).shape == (1, 3)


def test_the_same_rng_state_repeats_the_draws() -> None:
    for space in (Discrete(3), Box(2, -1.0, 1.0)):
        policy = RandomPolicy(space)
        assert np.array_equal(play(policy, 2, seed=9), play(policy, 2, seed=9))
        assert not np.array_equal(play(policy, 2, seed=9), play(policy, 2, seed=10))


def test_fish_pushes_match_the_recorded_draws() -> None:
    sample = json.loads((SAMPLES / "fish_5.json").read_text())
    pushes = play(RandomPolicy(Box(2, -1.0, 1.0)), agents=1, seed=sample["seed"], steps=5)
    assert np.allclose(pushes, np.asarray(sample["actions"]), atol=1e-4)

